GATEWAY_ARCHIVES={'inference': '', 'platform': ''}
GATEWAY_HASHES={'inference': 'fe182e7d035dbbf731b42a3572ed4d1b40269d0f287c351cc1c2486d4cc6ca0f', 'platform': '992d2b81ba58a3a5c65184d8b08a25a97c4fb51ab12795cf81c1765368db1864'}
GATEWAY_REVISIONS={'inference': '88b2cb09c57786931e1197b2c83ec38d326b1a0f', 'platform': 'c9d3c1990814831ed3ac205faa88273ec044dead'}
PAYLOAD=''
SOURCE_HASH='b9ec12d2e97c94fe8c40c592a6ef316f64d004fc4240b8215337ac02c3257a79'
PROMPTS=''
PROMPT_HASH='18212de5fefac798390c8500291ed0c4d615dca46a85e902f48b4dfc9e0f6a76'
ORIGINAL_PROMPT_HASH='04d34dc37b75fe45c4cdde7425d4805a44227244a4090492af9867de7fb46a66'
CORRECTED_CASES=[1, 2, 3, 6, 8, 36]
CORE='0fd7b3e32217bc9d9ab6659e72f5925a7d179751'
PLATFORM='7891c63b08ef9e2984510de94b7a4f0461dcd3f3'
PROMPT_COMMIT='366d94e5b7189353843392549e92f0c692683a03'
import base64,hashlib,io,json,os,subprocess,sys,tarfile,time,urllib.error,urllib.request
from pathlib import Path
subprocess.run([sys.executable,'-m','pip','install','pyrage>=1.4,<2','eth-account','fastapi>=0.115','sqlalchemy>=2','pydantic-settings','httpx','fpdf2>=2.8,<3'],check=True)
import torch
if not torch.cuda.is_available():raise RuntimeError('CUDA GPU required')
print('GPU',torch.cuda.get_device_name(0),flush=True)
raw=base64.b64decode(PAYLOAD)
if hashlib.sha256(raw).hexdigest()!=SOURCE_HASH:raise RuntimeError('archive hash mismatch')
root=Path('/kaggle/temp/assistant-eval-src');root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as outer:
    for member in outer.getmembers():
        with tarfile.open(fileobj=io.BytesIO(outer.extractfile(member).read()),mode='r:') as inner:
            inner.extractall(root,filter='data')
prompt_bytes=base64.b64decode(PROMPTS)
if hashlib.sha256(prompt_bytes).hexdigest()!=PROMPT_HASH:raise RuntimeError('prompt hash mismatch')
prompt_file=root/'experiments/assistant/arvind-prompts.jsonl';prompt_file.write_bytes(prompt_bytes)
sys.path[:0]=[str(root),str(root/'packages/ekido_core'),str(root/'experiments/assistant')]
from validate_prompt_set import validate
errors=validate(prompt_file)
if errors:raise RuntimeError('invalid prompts: '+repr(errors))
from huggingface_hub import hf_hub_download
model_path=hf_hub_download(repo_id='Qwen/Qwen2.5-1.5B-Instruct-GGUF',
    filename='qwen2.5-1.5b-instruct-q4_k_m.gguf',revision='91cad51170dc346986eccefdc2dd33a9da36ead9')
h=hashlib.sha256()
with open(model_path,'rb') as f:
    for chunk in iter(lambda:f.read(4*1024*1024),b''):h.update(chunk)
llama=Path('/kaggle/temp/llama.cpp')
subprocess.run(['git','init',str(llama)],check=True)
subprocess.run(['git','-C',str(llama),'fetch','--depth','1','https://github.com/ggml-org/llama.cpp.git','f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d'],check=True)
subprocess.run(['git','-C',str(llama),'checkout','--detach','FETCH_HEAD'],check=True)
import ctypes
ctypes.CDLL('libcuda.so.1')
driver_candidates=[Path('/usr/local/cuda/targets/x86_64-linux/lib/stubs/libcuda.so'),
                   Path('/usr/local/cuda/lib64/stubs/libcuda.so'),Path('/usr/lib/x86_64-linux-gnu/libcuda.so.1'),
                   Path('/usr/local/nvidia/lib64/libcuda.so.1'),Path('/usr/lib64/libcuda.so.1')]
# The container can mount the driver in a nonstandard location. After dlopen,
# /proc/self/maps provides the actual path the dynamic loader successfully used.
for line in Path('/proc/self/maps').read_text().splitlines():
    path=line.split()[-1]
    if path.startswith('/') and Path(path).name.startswith('libcuda.so'):
        driver_candidates.append(Path(path))
driver=next((p for p in driver_candidates if p.exists()),None)
if driver is None:raise RuntimeError('CUDA driver library unavailable for CMake')
print('CUDA_LINK_LIBRARY',str(driver),flush=True)
subprocess.run(['cmake','-S',str(llama),'-B',str(llama/'build'),'-DGGML_CUDA=ON','-DLLAMA_CURL=OFF',
                '-DLLAMA_BUILD_TESTS=OFF','-DCUDA_cuda_driver_LIBRARY='+str(driver)],check=True)
subprocess.run(['cmake','--build',str(llama/'build'),'--target','llama-server','-j','2'],check=True)
out=Path('/kaggle/working/assistant-model-eval');out.mkdir(parents=True,exist_ok=True)
log=(out/'llama-server.log').open('w',encoding='utf-8')
server=subprocess.Popen([str(llama/'build/bin/llama-server'),'-m',model_path,'--host','127.0.0.1','--port','19090',
                         '-ngl','99','-c','4096','--alias','Qwen/Qwen2.5-1.5B-Instruct'],stdout=log,stderr=subprocess.STDOUT)

try:
    for _ in range(180):
        if server.poll() is not None: raise RuntimeError('llama server exited; see log')
        try:
            with urllib.request.urlopen('http://127.0.0.1:19090/health',timeout=2) as response:
                if response.status==200: break
        except (OSError,urllib.error.URLError): pass
        time.sleep(2)
    else: raise RuntimeError('llama server did not start')
    import shutil, socket, threading
    subprocess.run([sys.executable,'-m','pip','install','uvicorn'],check=True)
    package_root=Path('/kaggle/temp/gateway-benchmark');package_root.mkdir(parents=True,exist_ok=True)
    for name,encoded in GATEWAY_ARCHIVES.items():
        raw=base64.b64decode(encoded)
        if hashlib.sha256(raw).hexdigest()!=GATEWAY_HASHES[name]: raise RuntimeError('source archive mismatch')
        dest=package_root/name;dest.mkdir()
        with tarfile.open(fileobj=io.BytesIO(raw),mode='r:') as archive: archive.extractall(dest,filter='data')
    env=os.environ.copy()
    if not shutil.which('cargo'):
        installer=package_root/'rustup.sh'
        with urllib.request.urlopen('https://sh.rustup.rs',timeout=60) as response: installer.write_bytes(response.read())
        subprocess.run(['sh',str(installer),'-y','--profile','minimal','--no-modify-path'],check=True,env=env)
        env['PATH']=str(Path.home()/'.cargo/bin')+os.pathsep+env['PATH']
    subprocess.run(['cargo','build','--release','--locked'],cwd=package_root/'inference',check=True,env=env)
    sys.path.insert(0,str(package_root/'platform'))
    import uvicorn
    from sqlalchemy import select
    from sqlalchemy.orm import Session
    from ekido_platform import accounts
    from ekido_platform.accounts import InferenceUsage,JobOwner
    from ekido_platform.main import Settings,create_app
    def free_port():
        with socket.socket() as sock:
            sock.bind(('127.0.0.1',0));return sock.getsockname()[1]
    platform_port,gateway_port=free_port(),free_port()
    token='local-benchmark-only-'+'x'*40
    cfg=Settings(database_url='sqlite:///'+str(package_root/'bench.db'),_env_file=None,
        inference_models_root=str(package_root),inference_internal_token=token,inference_rate_per_minute=500)
    app=create_app(cfg)
    with Session(app.state.engine) as db:
        user,_=accounts.finish_login(db,accounts.start_login(db,'bench@example.invalid'))
        org=accounts.create_org(db,user.id,'Synthetic benchmark')
        db.add(JobOwner(job_id='synthetic-job',org_id=org.id))
        _,key=accounts.create_api_key(db,org.id,user.id,'bench','test',['models.predict'])
        db.commit()
    (package_root/'model1.json').write_text(json.dumps({'job_id':'synthetic-job',
        'engine_url':'http://127.0.0.1:19090','engine_model':'Qwen/Qwen2.5-1.5B-Instruct','mode':'test'}))
    authority=uvicorn.Server(uvicorn.Config(app,host='127.0.0.1',port=platform_port,log_level='error',access_log=False))
    thread=threading.Thread(target=authority.run,daemon=True);thread.start()
    env.update(EKIDO_INFERENCE_ADDR=f'127.0.0.1:{gateway_port}',
        EKIDO_INFERENCE_AUTHORITY_URL=f'http://127.0.0.1:{platform_port}',EKIDO_INFERENCE_INTERNAL_TOKEN=token)
    gateway=subprocess.Popen([str(package_root/'inference/target/release/ekido-inference')],env=env,
        stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    try:
        base=f'http://127.0.0.1:{gateway_port}'
        for _ in range(120):
            if gateway.poll() is not None: raise RuntimeError('gateway exited')
            try:
                with urllib.request.urlopen(base+'/readyz',timeout=2) as r:
                    if r.status==200: break
            except (OSError,urllib.error.URLError): pass
            time.sleep(1)
        else: raise RuntimeError('gateway did not become ready')
        samples=[]
        for i in range(45):
            data=json.dumps({'model':'model1','messages':[{'role':'user','content':'Reply in one sentence: what is a refund?'}],
                             'max_tokens':16,'temperature':0}).encode()
            req=urllib.request.Request(base+'/v1/chat/completions',data=data,headers={'Content-Type':'application/json',
                                       'Authorization':'Bearer '+key})
            before=time.perf_counter()
            with urllib.request.urlopen(req,timeout=120) as response:
                body=json.load(response)
            elapsed=(time.perf_counter()-before)*1000
            if not body.get('choices') or not body.get('usage'): raise RuntimeError('invalid gateway response')
            if i>=5: samples.append({'latency_ms':elapsed,'usage':body['usage']})
        with Session(app.state.engine) as db:
            usage=db.scalars(select(InferenceUsage)).all()
            if len(usage)!=45 or any(row.status!='ok' for row in usage): raise RuntimeError('usage reconciliation failed')
        latencies=sorted(x['latency_ms'] for x in samples)
        import math
        result={'requests':len(samples),'warmup_requests':5,'concurrency':1,'gpu':torch.cuda.get_device_name(0),
                'latency_ms_p95_nearest_rank':latencies[math.ceil(.95*len(latencies))-1],
                'latency_ms_mean':sum(latencies)/len(latencies),'samples':samples,
                'source_revisions':GATEWAY_REVISIONS,'source_archive_sha256':GATEWAY_HASHES,
                'core_revision':CORE,'model_revision':'91cad51170dc346986eccefdc2dd33a9da36ead9',
                'model_sha256':h.hexdigest(),'llama_cpp_commit':'f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d',
                'usage_records_verified':len(usage),'scope':'Local synthetic sequential chat requests, not staging or production.'}
        out=Path('/kaggle/working/gateway-benchmark');out.mkdir(exist_ok=True)
        (out/'results.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
        print('RESULT',json.dumps({k:result[k] for k in ('requests','latency_ms_p95_nearest_rank','latency_ms_mean','gpu')}),flush=True)
    finally:
        gateway.terminate()
        try: gateway.wait(timeout=15)
        except subprocess.TimeoutExpired: gateway.kill();gateway.wait()
        authority.should_exit=True;thread.join(timeout=10);app.state.engine.dispose()
finally:
    server.terminate()
    try: server.wait(timeout=15)
    except subprocess.TimeoutExpired: server.kill();server.wait()
    log.close()
